def run_length_encode(s):
    out = []
    for ch in s:
        if out and out[-1][0] == ch:
            out[-1][1] += 1
        else:
            out.append([ch, 1])
    return out

def is_balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    st = []
    for c in s:
        if c in '([{':
            st.append(c)
        elif c in pairs:
            if not st or st.pop() != pairs[c]:
                return False
    return not st

def merge_intervals(iv):
    out = []
    for s, e in sorted(iv):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

def count_islands(grid):
    seen = set()
    n = 0
    for r in range(len(grid)):
        for c in range(len(grid[0]) if grid else 0):
            if grid[r][c] == 1 and (r, c) not in seen:
                n += 1
                st = [(r, c)]
                while st:
                    y, x = st.pop()
                    if (y, x) in seen or not (0 <= y < len(grid) and 0 <= x < len(grid[0])) or grid[y][x] != 1:
                        continue
                    seen.add((y, x))
                    st += [(y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)]
    return n

def roman_to_int(s):
    v = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    t = 0
    for i, ch in enumerate(s):
        if i + 1 < len(s) and v[ch] < v[s[i + 1]]:
            t -= v[ch]
        else:
            t += v[ch]
    return t

def word_frequencies(text):
    d = {}
    for w in text.split():
        w = w.strip('.,!?').lower()
        if w:
            d[w] = d.get(w, 0) + 1
    return d

def binary_search(xs, target):
    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        m = (lo + hi) // 2
        if xs[m] == target:
            return m
        if xs[m] < target:
            lo = m + 1
        else:
            hi = m - 1
    return -1

def primes_upto(n):
    if n < 2:
        return []
    s = [True] * (n + 1)
    s[0] = s[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i::i] = [False] * len(s[i * i::i])
    return [i for i, p in enumerate(s) if p]
